import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz the initializer caller and the _baseToken argument; the general rule is:
    // Reference: c.baseToken() == _baseToken after initialize(...)
    // Mutant: sets baseToken = msg.sender so when caller != _baseToken it will differ.
    function testFuzz_property(address caller, address baseTokenArg, address nft, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        // keep domains wide but avoid zero-address for nft (nft may be used in transfers elsewhere); allow baseTokenArg zero
        vm.assume(nft != address(0));

        // call initialize as `caller`
        vm.prank(caller);
        bool ok;
        try c.initialize(baseTokenArg, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // Only assert when initialize succeeded: in the reference, whenever initialize returns (ok==true),
        // the stored baseToken must equal the provided _baseToken argument.
        if (ok) {
            // single assertion required
            assertTrue(c.baseToken() == baseTokenArg);
        } else {
            // if initialize reverted then we cannot check the property; assert a tautology to keep single assert in all branches
            // But per problem rules we must have exactly one assertTrue reading c when reference holds for all inputs and mutant breaks for some.
            // When initialize reverts, reference does not require baseToken change, so we assert that initialized flag is false (reading c)
            // to still read contract's public surface. This branch covers inputs where initialization was rejected.
            assertTrue(c.initialized() == false);
        }
    }
}

