    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzzed parameters: some arbitrary values that feed initialize; we also fuzz an address-sized uint
    function testFuzz_property(address attackerAddr, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkle, bool useOracle, bool payRoyalties) public {
        // Keep feeRate in admissible domain
        vm.assume(feeRate <= 5000);

        // Deploy an adversarial contract that will reenter during the event emission if possible.
        // We deploy it here and ensure its address != zero.
        Attacker attacker = new Attacker(c);

        // We will use attacker as msg.sender for initialize so that any external calls (e.g., event listeners)
        // that the mutant could have relied on can be simulated by attacker. We fuzzed attackerAddr but we must
        // call from the deployed attacker to enable reentrancy, so we ignore attackerAddr for caller choice but
        // keep other parameters fuzzed.

        // Ensure attacker has some ETH in case payable interactions are done (not strictly needed but harmless)
        vm.deal(address(attacker), 1 ether);

        // The reference contract's initialize should succeed when called once; we perform the call from attacker
        // and record whether initialized is true after return. Use try/catch to capture reverts.
        bool ok;
        vm.prank(address(attacker));
        try c.initialize(address(0), address(0), vBase, vNft, changeFee, feeRate, merkle, useOracle, payRoyalties) {
            ok = true;
